using System;
using System.Collections.Generic;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.IdentityModel.Tokens;

namespace AuthenticationAuthorizationDemo
{
    // ==================== JWT 服务 ====================
    public class JwtService
    {
        private readonly string _secret;
        private readonly string _issuer;
        private readonly string _audience;

        public JwtService(string secret, string issuer, string audience)
        {
            _secret = secret;
            _issuer = issuer;
            _audience = audience;
        }

        public string GenerateToken(int userId, string username, string role)
        {
            var claims = new[]
            {
                new Claim(ClaimTypes.NameIdentifier, userId.ToString()),
                new Claim(ClaimTypes.Name, username),
                new Claim(ClaimTypes.Role, role),
                new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString())
            };

            var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_secret));
            var credentials = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);

            var token = new JwtSecurityToken(
                issuer: _issuer,
                audience: _audience,
                claims: claims,
                expires: DateTime.UtcNow.AddMinutes(15), // 短过期
                signingCredentials: credentials);

            return new JwtSecurityTokenHandler().WriteToken(token);
        }

        public ClaimsPrincipal? ValidateToken(string token)
        {
            var handler = new JwtSecurityTokenHandler();
            var parameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidateAudience = true,
                ValidateLifetime = true,
                ValidateIssuerSigningKey = true,
                ValidIssuer = _issuer,
                ValidAudience = _audience,
                IssuerSigningKey = new SymmetricSecurityKey(
                    Encoding.UTF8.GetBytes(_secret))
            };

            try
            {
                return handler.ValidateToken(token, parameters, out _);
            }
            catch (SecurityTokenException)
            {
                return null;
            }
        }
    }

    // ==================== 基于策略的授权：最小年龄 ====================
    public class MinimumAgeRequirement : IAuthorizationRequirement
    {
        public int MinimumAge { get; }
        public MinimumAgeRequirement(int minimumAge) => MinimumAge = minimumAge;
    }

    public class MinimumAgeHandler : AuthorizationHandler<MinimumAgeRequirement>
    {
        protected override Task HandleRequirementAsync(
            AuthorizationHandlerContext context,
            MinimumAgeRequirement requirement)
        {
            var claim = context.User.FindFirst(ClaimTypes.DateOfBirth);
            if (claim == null) return Task.CompletedTask; // 没有出生日期，不通过

            var birthDate = DateTime.Parse(claim.Value);
            var age = DateTime.Today.Year - birthDate.Year;
            if (birthDate > DateTime.Today.AddYears(-age)) age--;

            if (age >= requirement.MinimumAge)
                context.Succeed(requirement);

            return Task.CompletedTask;
        }
    }

    // ==================== 基于资源的授权：文章操作 ====================
    public class Article { public int Id { get; set; } public string AuthorId { get; set; } = ""; }

    public static class ArticleOperations
    {
        public static readonly OperationAuthorizationRequirement Edit =
            new() { Name = "Edit" };
    }

    public class ArticleAuthorizationHandler :
        AuthorizationHandler<OperationAuthorizationRequirement, Article>
    {
        protected override Task HandleRequirementAsync(
            AuthorizationHandlerContext context,
            OperationAuthorizationRequirement requirement,
            Article resource)
        {
            var userId = context.User.FindFirst(ClaimTypes.NameIdentifier)?.Value;
            if (requirement.Name == "Edit" && resource.AuthorId == userId)
                context.Succeed(requirement);

            return Task.CompletedTask;
        }
    }

    // ==================== 控制器：三种授权模型的使用 ====================
    [ApiController]
    [Route("api/[controller]")]
    public class ArticlesController : ControllerBase
    {
        private readonly IAuthorizationService _authService;

        public ArticlesController(IAuthorizationService authService)
            => _authService = authService;

        // 角色授权：只有 Admin 能访问
        [HttpGet("admin")]
        [Authorize(Roles = "Admin")]
        public IActionResult AdminOnly() => Ok("Admin area");

        // 策略授权：年龄 >= 18
        [HttpGet("adult")]
        [Authorize(Policy = "AtLeast18")]
        public IActionResult AdultContent() => Ok("Adult content");

        // 资源授权：文章作者才能编辑
        [HttpPut("{id}")]
        [Authorize]
        public async Task<IActionResult> Edit(int id)
        {
            var article = new Article { Id = id, AuthorId = "1" };

            var result = await _authService.AuthorizeAsync(
                User, article, ArticleOperations.Edit);

            if (!result.Succeeded) return Forbid();

            return Ok(article);
        }
    }

    // ==================== DI 注册 ====================
    public static class AuthExtensions
    {
        public static IServiceCollection AddDemoAuth(
            this IServiceCollection services,
            string jwtSecret, string issuer, string audience)
        {
            services.AddSingleton(new JwtService(jwtSecret, issuer, audience));

            services.AddAuthentication(options =>
            {
                options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
                options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
            })
            .AddJwtBearer(options =>
            {
                options.TokenValidationParameters = new TokenValidationParameters
                {
                    ValidateIssuer = true,
                    ValidateAudience = true,
                    ValidateLifetime = true,
                    ValidateIssuerSigningKey = true,
                    ValidIssuer = issuer,
                    ValidAudience = audience,
                    IssuerSigningKey = new SymmetricSecurityKey(
                        Encoding.UTF8.GetBytes(jwtSecret))
                };
            })
            .AddCookie(CookieAuthenticationDefaults.AuthenticationScheme, options =>
            {
                options.LoginPath = "/Account/Login";
                options.ExpireTimeSpan = TimeSpan.FromHours(1);
                options.SlidingExpiration = true;
            });

            services.AddAuthorization(options =>
            {
                options.AddPolicy("AtLeast18", policy =>
                    policy.Requirements.Add(new MinimumAgeRequirement(18)));
            });

            services.AddSingleton<IAuthorizationHandler, MinimumAgeHandler>();
            services.AddSingleton<IAuthorizationHandler, ArticleAuthorizationHandler>();

            return services;
        }
    }
}
